// Current state of every supplier risk: the latest event of each risk instance, whether the risk is open or closed
let CensysRisks_view = view () {
    CensysRiskEvents
    | summarize arg_max(InsertedAt, *) by RiskInstanceId
};
CensysRisks_view

// Current state of every supplier risk: the latest event of each risk instance, whether the risk is open or closed
let CensysRisks_view = view () {
    CensysRiskEvents
    | summarize arg_max(InsertedAt, *) by RiskInstanceId
};
CensysRisks_view

// New events are selected by the time they reached Sentinel (IngestedAt), not by the Censys insert time,
// so a delay between Censys and the connector can never make an event fall between two runs.
// Each run covers 60 minutes that end 5 minutes ago, and consecutive runs are contiguous, so no event is alerted twice.
//
// OPTIONAL - follow the whole life of a risk instance (reopened events of any severity, and resolved events of risks that
// were alerted before). To use it, uncomment the two "let" lines below, comment out the line "Default" in the query, uncomment
// the line "Full lifecycle", and in the rule settings set the query period to 7 days and the incident grouping look-back to 7 days.
// let Alertable = materialize(CensysRiskEvents | where ChangeType == "reopened" or (ChangeType == "opened" and Severity in ("CRITICAL", "HIGH")));
// let TrackedRisks = Alertable | distinct RiskInstanceId;
CensysRiskEvents
| where IngestedAt between (ago(65m) .. ago(5m))
// Default: opened or reopened risks with CRITICAL or HIGH severity
| where ChangeType in ("opened", "reopened") and Severity in ("CRITICAL", "HIGH")
// Full lifecycle (needs the optional "let" lines above):
// | where (ChangeType == "reopened" or (ChangeType == "opened" and Severity in ("CRITICAL", "HIGH"))) or (ChangeType == "resolved" and RiskInstanceId in (TrackedRisks))
//
// Optional filters: remove the leading // of a line to use it. Each line narrows the alerts further, and several lines can be combined.
// Do not remove or change the IngestedAt window above, it keeps every event alerted exactly once.
// | where Confidence >= 0.8                           // only findings with a confidence of 80% or more
// | where Severity == "CRITICAL"                      // only CRITICAL risks (Censys severities: CRITICAL, HIGH, MEDIUM, LOW)
// | where ChangeType == "opened"                      // only newly opened risks, skip reopened risks
// | where RapidResponse == true                       // only actively exploited (rapid response) risks
// | where RiskCategory == "VULNERABILITY"             // VULNERABILITY, MISCONFIGURATION, EXPOSURE or THREAT
// | where SupplierDisplayName in ("OpenAI", "Harvey") // only these suppliers
// | where CveId != ""                                 // only risks that have a CVE id
// | where RiskName has "Log4Shell"                    // only risks whose name contains this text
// | where AssetType == "host"                         // asset type: host or web
| extend SentinelSeverity = case(
    Severity in ("CRITICAL", "HIGH"), "High",
    Severity == "MEDIUM", "Medium",
    Severity == "LOW", "Low",
    "Informational")
| project TimeGenerated, IngestedAt, EventId, InsertedAt, OccurredAt, ChangeType, RiskInstanceId, Severity, SentinelSeverity,
    RiskCategory, RiskName, Description, CveId, RapidResponse, SupplierDisplayName,
    AssetName, AssetHostname, AssetIp, ServicePort, ServiceProtocol, Evidence, ResolveTime, ResolveReason, PlatformUrl
